mapper.update:
UPDATE campaign_conversation
   SET reserved = TRUE,
       revision = 0,
       session_format = NULL,
       session_hash = NULL,
       session_bytes = NULL,
       created_at = #{createdAt, jdbcType=TIMESTAMP_WITH_TIMEZONE},
       updated_at = #{updatedAt, jdbcType=TIMESTAMP_WITH_TIMEZONE},
       expires_at = #{expiresAt, jdbcType=TIMESTAMP_WITH_TIMEZONE}
 WHERE tenant_id = #{tenantId}
   AND program_id = #{programId}
   AND user_id = #{userId}
   AND conversation_id = #{conversationId}
   AND run_id = #{runId}

UPDATE campaign_conversation
   SET revision = #{revision},
       session_format = #{sessionFormat},
       session_hash = #{sessionHash},
       session_bytes = #{sessionBytes, jdbcType=BINARY},
       updated_at = #{updatedAt, jdbcType=TIMESTAMP_WITH_TIMEZONE},
       expires_at = #{expiresAt, jdbcType=TIMESTAMP_WITH_TIMEZONE}
 WHERE tenant_id = #{tenantId}
   AND program_id = #{programId}
   AND user_id = #{userId}
   AND conversation_id = #{conversationId}
   AND run_id = #{runId}
   AND revision = #{expectedRevision}

mapper.select:
SELECT conversation_id
  FROM campaign_conversation
 WHERE tenant_id = #{tenantId}
   AND program_id = #{programId}
   AND user_id = #{userId}
   AND expires_at > #{now, jdbcType=TIMESTAMP_WITH_TIMEZONE}
   AND NOT (conversation_id = #{excludeConversationId} AND run_id = #{excludeRunId})
 ORDER BY expires_at ASC
 LIMIT #{limit}

SELECT conversation_id, run_id, revision, session_format, session_hash, session_bytes,
       created_at, updated_at
  FROM campaign_conversation
 WHERE tenant_id = #{tenantId}
   AND program_id = #{programId}
   AND user_id = #{userId}
   AND expires_at > #{now, jdbcType=TIMESTAMP_WITH_TIMEZONE}
   AND (reserved = TRUE OR session_bytes IS NOT NULL)
 ORDER BY updated_at DESC, conversation_id ASC, run_id ASC
 LIMIT #{limit}

SELECT reserved, revision, session_format, session_hash, session_bytes
  FROM campaign_conversation
 WHERE tenant_id = #{tenantId}
   AND program_id = #{programId}
   AND user_id = #{userId}
   AND conversation_id = #{conversationId}
   AND run_id = #{runId}

mapper.delete:
DELETE FROM campaign_conversation
 WHERE ctid IN (
       SELECT ctid
         FROM campaign_conversation
        WHERE tenant_id = #{tenantId}
          AND program_id = #{programId}
          AND user_id = #{userId}
          AND expires_at <= #{sweepBefore, jdbcType=TIMESTAMP_WITH_TIMEZONE}
        ORDER BY expires_at ASC
        LIMIT #{limit})

DELETE FROM campaign_conversation_outcome
 WHERE ctid IN (
       SELECT ctid
         FROM campaign_conversation_outcome
        WHERE tenant_id = #{tenantId}
          AND program_id = #{programId}
          AND user_id = #{userId}
          AND conversation_id = #{conversationId}
          AND run_id = #{runId}
          AND expires_at <= #{sweepBefore, jdbcType=TIMESTAMP_WITH_TIMEZONE}
        ORDER BY expires_at ASC
        LIMIT #{limit})

